    fun random(excluding: String? = null): String {
        if (all.isEmpty()) return "Сахар высокий, шуток нет… шутка."
        if (all.size == 1) return all.first()
        var pick: String
        do {
            pick = all.random()
        } while (excluding != null && pick == excluding && all.size > 1)
        return pick
    }
}
